```rust
//@ expect: accept
//@ edition: 2021
// Impls that leave out `Write::write_fmt` (a counter's, `StderrLock`'s) run the trait's
// provided body: called directly, by `write!`, and through a `dyn Write` vtable slot.
use std::io::{self, Write};
struct Count(usize);
impl Write for Count {
    fn write(&mut self, bytes: &[u8]) -> io::Result<usize> {
        self.0 += bytes.len();
        Ok(bytes.len())
    }
    fn flush(&mut self) -> io::Result<()> {
        Ok(())
    }
}
fn main() {
    let mut count = Count(0);
    count.write_fmt(format_args!("{}-{}", 12, 345)).unwrap();
    write!(count, "{:>4}", 6).unwrap();
    let slot: &mut dyn Write = &mut count;
    slot.write_fmt(format_args!("{}", "seven")).unwrap();
    let mut err = io::stderr().lock();
    err.write_fmt(format_args!("to stderr {}\n", 8)).unwrap();
    let slot: &mut dyn Write = &mut err;
    writeln!(slot, "to stderr through dyn").unwrap();
    println!("{}", count.0);
}
```

